/**
 * The numbered list of sources a reply cites (`design/components/source-list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/source-list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { Each, Icon, claimSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/source-list.module.css'

export interface CitationSource {
  title: string
  href: string
  domain?: string
  snippet?: string
}

export interface SourceListProps {
  /**
   * The list's accessible name, such as "Sources" in the app's language.
   */
  label: string
  /**
   * The sources in the order the reply numbers them, rendered as given and never sorted.
   */
  sources: CitationSource[]
}

/** The numbered list of sources a reply cites. */
export default function SourceList(given: SourceListProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <>
        {props.sources.length > 0 ? (
          <section class={styles.root} aria-label={props.label} data-member="source-list">
            {/* heading */}
            <span class={styles.heading} aria-hidden="true">
              <Icon name="cite" size="sm" />
              {props.label}
            </span>
            {/* list */}
            <ol class={styles.list}>
              <Each of={props.sources} by={(_source, position) => position} renew>
                {(source, position) => (
                  <li class={styles.item}>
                    {/* index */}
                    <span class={styles.index} aria-hidden="true">
                      {position() + 1}
                    </span>
                    {/* body */}
                    <span class={styles.body}>
                      {/* title */}
                      <a class={styles.title} href={source.href} target="_blank" rel="noreferrer">
                        {source.title}
                        <span class={styles.glyph}>
                          <Icon name="open-external" size="sm" />
                        </span>
                      </a>
                      {source.domain !== undefined ? (
                        <span class={styles.domain}>{source.domain}</span>
                      ) : null}
                      {source.snippet !== undefined ? (
                        <span class={styles.snippet}>{source.snippet}</span>
                      ) : null}
                    </span>
                  </li>
                )}
              </Each>
            </ol>
          </section>
        ) : null}
      </>
    )
  })
}
